Tool response:
Tool: update_repair_order_status
Description: Update the status of a repair order identified by its order number.
Parameters:
    {
      "type": "object",
      "properties": {
        "order_number": {
          "type": "string",
          "description": "The order number of the repair order to update",
          "title": "Order Number"
        },
        "status": {
          "type": "string",
          "title": "Status",
          "description": "The new status for the repair order"
        }
      },
      "required": [
        "order_number",
        "status"
      ]
    }

Tool response:
Tool: create_labor_line
Description: Create a new labor line item for a specified repair order.
Parameters:
    {
      "type": "object",
      "properties": {
        "repair_order_id": {
          "type": "integer",
          "title": "Repair Order Id",
          "description": "The ID of the repair order to associate this labor line with"
        },
        "description": {
          "type": "string",
          "title": "Description",
          "description": "Description of the labor performed"
        },
        "hours": {
          "type": "number",
          "exclusiveMinimum": 0.0,
          "title": "Hours",
          "description": "Number of hours worked"
        },
        "rate": {
          "type": "number",
          "minimum": 0.0,
          "title": "Rate",
          "description": "Hourly rate for the labor"
        }
      },
      "required": [
        "repair_order_id",
        "description",
        "hours",
        "rate"
      ]
    }
